<script lang="ts">
 import type {resumoDashboard} from '#lib/server/dashboard';
 let {resumo}:{resumo:Awaited<ReturnType<typeof resumoDashboard>>}=$props();
 let mostrarDados=$state(false);
 const max=$derived(Math.max(1,...resumo.meses.flatMap(m=>[m.disponiveis,m.escalados,m.atendidas])));
 const series=[{campo:'escalados',titulo:'Obreiros escalados',cor:'#037fb0'},{campo:'disponiveis',titulo:'Obreiros disponíveis',cor:'#72936d'},{campo:'atendidas',titulo:'Escalas atendidas',cor:'#dc9a39'}] as const;
 const linha=(campo:typeof series[number]['campo'])=>resumo.meses.map((m,i)=>`${40+i*43},${210-m[campo]/max*170}`).join(' ');
</script>
<section aria-label="Resumo da Área"><h1 class="titulo">Resumo da Área</h1><p class="mt-2 text-sm text-gray-500">Mês atual · {resumo.meses[resumo.mesAtual].mes}/{resumo.ano}</p><div class="grid gap-3 mt-4 sm:grid-cols-3" data-testid="cards-coordenador">{#each [{n:resumo.congregacoes,t:'Total de Congregações'},{n:resumo.disponiveis,t:'Obreiros disponíveis no mês atual'},{n:resumo.escalados,t:'Obreiros escalados no mês atual'}] as c (c.t)}<article class="cartao"><strong class="text-3xl text-marca-escuro">{c.n}</strong><p class="text-sm mt-2">{c.t}</p></article>{/each}</div>
<section class="cartao mt-5" aria-label="Movimentação das Escalas"><div class="flex flex-wrap items-center justify-between gap-3"><h2 class="font-semibold">Movimentação das Escalas · {resumo.ano}</h2><button type="button" class="btn btn-secundario" aria-expanded={mostrarDados} aria-controls="dados-mensais" onclick={()=>mostrarDados=!mostrarDados}>{mostrarDados?'Ocultar dados':'Ver dados por mês'}</button></div><div class="mt-3 flex flex-wrap gap-3 text-xs">{#each series as s (s.campo)}<span class="flex items-center gap-2"><span class="inline-block size-2 rounded-full" style:background={s.cor}></span>{s.titulo}</span>{/each}</div>
<svg class="w-full mt-4" style="height:220px" viewBox="0 0 550 250" role="img" aria-labelledby="grafico-titulo grafico-descricao"><title id="grafico-titulo">Movimentação mensal das escalas</title><desc id="grafico-descricao">Comparação entre obreiros disponíveis, obreiros escalados e escalas atendidas. Use Ver dados por mês para consultar os valores.</desc>{#each [0,.5,1] as v (v)}<line x1="35" x2="520" y1={210-v*170} y2={210-v*170} stroke="#e5e7eb"/><text x="26" y={214-v*170} text-anchor="end" font-size="11" fill="#6b7280">{Math.round(max*v)}</text>{/each}{#each series as s (s.campo)}<polyline points={linha(s.campo)} fill="none" stroke={s.cor} stroke-width="2.5"/>{/each}{#each resumo.meses as m,i (m.mes)}<text x={40+i*43} y="235" text-anchor="middle" font-size="10" fill="#6b7280">{m.mes}</text>{/each}</svg>
<div id="dados-mensais" hidden={!mostrarDados} class="overflow-x-auto mt-3"><table class="w-full text-xs"><caption class="text-left mb-2 font-medium">Dados por mês · {resumo.ano}</caption><thead><tr><th class="text-left p-2">Mês</th>{#each series as s (s.campo)}<th class="p-2">{s.titulo}</th>{/each}</tr></thead><tbody>{#each resumo.meses as m (m.mes)}<tr class="border-t"><th class="text-left p-2">{m.mes}</th>{#each series as s (s.campo)}<td class="text-center p-2">{m[s.campo]}</td>{/each}</tr>{/each}</tbody></table></div></section></section>
